## Three.js 集成

直接使用 WebGL 较为底层，**Three.js** 是最流行的 3D 库，提供场景图、材质系统、灯光和相机等高级抽象。

```typescript
import * as THREE from 'three';

function createScene(): { scene: THREE.Scene; camera: THREE.PerspectiveCamera; renderer: THREE.WebGLRenderer } {
  const scene = new THREE.Scene();

  const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
  camera.position.z = 5;

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(window.devicePixelRatio);
  document.body.appendChild(renderer.domElement);

  const geometry = new THREE.BoxGeometry(1, 1, 1);
  const material = new THREE.MeshStandardMaterial({ color: 0x3b82f6 });
  const cube = new THREE.Mesh(geometry, material);
  scene.add(cube);

  const light = new THREE.DirectionalLight(0xffffff, 1);
  light.position.set(5, 5, 5);
  scene.add(light);
  scene.add(new THREE.AmbientLight(0x404040));

  function animate(): void {
    requestAnimationFrame(animate);
    cube.rotation.x += 0.01;
    cube.rotation.y += 0.01;
    renderer.render(scene, camera);
  }

  animate();

  return { scene, camera, renderer };
}
```

```mermaid
flowchart TD
    Scene["Scene\n(场景)"]
    Scene --> Mesh["Mesh\n(网格)"]
    Mesh --> Geometry["Geometry\n(几何体)"]
    Mesh --> Material["Material\n(材质)"]
    Scene --> Light["Light\n(灯光)"]
    Scene --> Camera["Camera\n(相机)"]
    Camera --> Renderer["WebGLRenderer"]
    Renderer --> Canvas["Canvas 输出"]
```

